package com.hbm.item.designator.advanced;
import api.hbm.item.IDesignatorItem;import java.util.List;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.level.Level;import net.minecraft.world.phys.Vec3;
/** Shared source-identical readiness and coordinate tooltip of the two real variants. */
public abstract class CoordinateDesignatorItem extends Item implements IDesignatorItem{protected CoordinateDesignatorItem(){super(new Properties().stacksTo(1));}@Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){if(stack.has(DataComponents.CUSTOM_DATA)){var tag=stack.get(DataComponents.CUSTOM_DATA).copyTag();lines.add(Component.translatable("item.hbm.designator.coordinates"));lines.add(Component.literal("X: "+tag.getInt("xCoord")));lines.add(Component.literal("Z: "+tag.getInt("zCoord")));}else lines.add(Component.translatable("item.hbm.designator.select_target"));}@Override public boolean isReady(Level level,ItemStack stack,int x,int y,int z){return stack.has(DataComponents.CUSTOM_DATA);}@Override public Vec3 getCoords(Level level,ItemStack stack,int x,int y,int z){var tag=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();return new Vec3(tag.getInt("xCoord"),0,tag.getInt("zCoord"));}}
